  // ── 阵营说明 ──
  '钢铁与工厂的工业强国，信奉火力与装甲。': 'Potência industrial de aço e fábricas, que confia no poder de fogo e na blindagem.',  // FACTIONS.1.culture
  '履带车辆防御 +5%；陆上单位在兵工厂的修理费 −20%。': 'Veículos de esteira têm defesa +5%; unidades terrestres têm custo de reparo −20% em fábricas.',  // FACTIONS.1.trait
  '海洋与天空的联邦，重视技术与后勤。': 'Federação do mar e do céu, que valoriza a tecnologia e a logística.',  // FACTIONS.2.culture
  '航空单位和舰船视野 +1；航空单位在机场、舰船在港口的修理费 −20%。': 'Unidades aéreas e navios têm visão +1; custo de reparo −20% para unidades aéreas em aeroportos e navios em portos.',  // FACTIONS.2.trait
  '山林与雪原的游击之民，擅长地形与隐蔽。': 'Povo guerrilheiro das matas e dos campos de neve, hábil no uso do terreno e da ocultação.',  // FACTIONS.3.culture
  '步兵类单位造价 −5%；位于森林、山地的步兵类单位防御 +10%；中型坦克、重型坦克、火箭炮造价 +5%。': 'Soldados têm custo −5%; soldados em florestas e montanhas têm defesa +10%; tanques médios, tanques pesados e lança-foguetes têm custo +5%.',  // FACTIONS.3.trait
  '商路与黄金的城邦联盟，凭借财力与城墙作战。': 'Liga de cidades-estado das rotas comerciais e do ouro, que luta com riqueza e muralhas.',  // FACTIONS.4.culture
  '城市收入 +10%；位于建筑的单位防御 +5%，位于平原的单位防御 −5%。': 'Cidades têm renda +10%; unidades em edifícios têm defesa +5%, e unidades em planícies têm defesa −5%.',  // FACTIONS.4.trait

  // ── 阵营研究 ──
