  '可选用独有的“特高”档研究经费：每回合支付 900 资金，获得 30 研究点。': 'Permite usar o nível exclusivo “Máxima” de verba de pesquisa: você paga 900 fundos por turno e recebe 30 pontos de pesquisa.',  // FACTIONS.4.research.desc

