  // ── 兵种说明 ──
  '造价低廉，可占领建筑，可进入山地与河流。': 'Tem custo baixo, pode capturar edifícios e pode entrar em montanhas e rios.',  // UNITS.inf.desc
  '装备火箭筒的步兵，可占领建筑，对坦克伤害较高，在山地、河流上的移动消耗为 1。': 'Infantaria com bazuca: pode capturar edifícios, causa dano alto a tanques e tem custo de movimento 1 em montanhas e rios.',  // UNITS.mech.desc
  '射程 2–4 的远程步兵，擅长攻击步兵类单位，也可攻击轻型车辆和直升机。在山地上射程 +1。移动后不可攻击。': 'Infantaria de longo alcance, com alcance 2–4; é eficaz contra soldados e também pode atacar veículos leves e helicópteros. Em montanhas, alcance +1. Não pode atacar após se mover.',  // UNITS.snp.desc
  '射程 1–2，移动后仍可攻击。攻击时目标的地形防御减半，擅长攻击位于建筑、森林、山地的步兵类单位。攻击 2 格外的目标时不受反击。在山地上射程 +1。不可攻击航空单位和舰船，不可占领。': 'Alcance 1–2; pode atacar após se mover. Ao atacar, a defesa de terreno do alvo cai pela metade; é eficaz contra soldados em edifícios, florestas e montanhas. Não sofre contra-ataque ao atacar alvos a 2 casas. Em montanhas, alcance +1. Não pode atacar unidades aéreas nem navios e não pode capturar.',  // UNITS.grn.desc
  '射程 1，攻击时无视目标的地形防御，擅长攻击位于建筑、山地的步兵类单位。迷雾开启时，可发现周围 8 格森林、废墟中的隐蔽单位。不敌远程单位和车辆，不可攻击航空单位和舰船，不可占领。': 'Alcance 1; ao atacar, ignora a defesa de terreno do alvo e é eficaz contra soldados em edifícios e montanhas. Com a névoa ativada, revela unidades ocultas em florestas e ruínas nas 8 casas ao redor. É fraco contra unidades de longo alcance e veículos, não pode atacar unidades aéreas nem navios e não pode capturar.',  // UNITS.flm.desc
  '无武装。相邻的己方步兵类单位每回合恢复 2 HP（无需支付资金）。多名医护兵的效果不叠加。': 'Sem armas. Seus soldados adjacentes recuperam 2 HP por turno (sem pagar fundos). O efeito de vários médicos não se acumula.',  // UNITS.mdc.desc
  '乘坐摩托车的步兵，可占领建筑，移动力高，适合占领远处的建筑。不可进入山地。': 'Infantaria de motocicleta: pode capturar edifícios e tem movimento alto, ideal para capturar edifícios distantes. Não pode entrar em montanhas.',  // UNITS.bik.desc
  '陆上单位中移动力最高，擅长攻击步兵类单位和无掩护的火炮，不敌坦克。': 'Tem o maior movimento entre as unidades terrestres, é eficaz contra soldados e artilharia desprotegida e é fraco contra tanques.',  // UNITS.rec.desc
  '陆上主力，造价较低，攻击与防御均衡。': 'Força principal em terra, com custo relativamente baixo e ataque e defesa equilibrados.',  // UNITS.tnk.desc
  '攻击与防御高于轻型坦克，造价适中。': 'Ataque e defesa superiores aos do tanque leve, com custo moderado.',  // UNITS.med.desc
  '陆上单位中攻击与防御最高，造价高，移动力低。': 'Tem o maior ataque e a maior defesa entre as unidades terrestres, com custo alto e movimento baixo.',  // UNITS.hvy.desc
  '射程 2–3，可攻击舰船。移动后不可攻击，不可攻击相邻的敌方单位。': 'Alcance 2–3; pode atacar navios. Não pode atacar após se mover nem atacar unidades inimigas adjacentes.',  // UNITS.art.desc
  '射程 3–5，射程长于自行火炮，擅长攻击重型车辆。移动后不可攻击。': 'Alcance 3–5, maior que o da artilharia; é eficaz contra veículos pesados. Não pode atacar após se mover.',  // UNITS.rkt.desc
  '射程 1，擅长攻击航空单位，对步兵类单位伤害也较高。': 'Alcance 1; é eficaz contra unidades aéreas e também causa dano alto a soldados.',  // UNITS.aa.desc
  '无武装。相邻的己方车辆、航空单位、舰船每回合恢复 1 HP（无需支付资金）。': 'Sem armas. Seus veículos, unidades aéreas e navios adjacentes recuperam 1 HP por turno (sem pagar fundos).',  // UNITS.rep.desc
  '移动不受地形影响，擅长攻击陆上单位，不敌防空车。': 'Seu movimento ignora o terreno; é eficaz contra unidades terrestres e fraco contra antiaéreos.',  // UNITS.cop.desc
  '可攻击陆上单位和直升机，造价低于轰炸机。': 'Pode atacar unidades terrestres e helicópteros; custa menos que o bombardeiro.',  // UNITS.atk.desc
  '对陆上单位和舰船伤害极高，不可攻击航空单位。': 'Causa dano altíssimo a unidades terrestres e navios; não pode atacar unidades aéreas.',  // UNITS.bmb.desc
  '造价低廉的小型舰船，可攻击岸边的陆上单位，擅长攻击登陆艇。': 'Navio pequeno de custo baixo; pode atacar unidades terrestres na costa e é eficaz contra barcaças.',  // UNITS.gbt.desc
  '兼具防空与反潜能力，擅长攻击潜艇和航空单位。': 'Combina defesa antiaérea e antissubmarino; é eficaz contra submarinos e unidades aéreas.',  // UNITS.dst.desc
  '射程 2–6，可攻击陆上单位和舰船，伤害较高。移动后不可攻击。': 'Alcance 2–6; pode atacar unidades terrestres e navios, com dano alto. Não pode atacar após se mover.',  // UNITS.bsh.desc
  '无武装。可搭载 2 个陆上单位，靠岸后卸载。': 'Sem armas. Pode transportar 2 unidades terrestres e desembarcá-las na costa.',  // UNITS.lnd.desc

