  // ── 地形说明 ──
  '轮式车辆的移动消耗为 3。': 'Veículos de rodas têm custo de movimento 3.',  // TERRAIN.waste.note
  '陆上单位的移动消耗增加，轮式车辆不可进入。': 'O custo de movimento das unidades terrestres aumenta; veículos de rodas não podem entrar.',  // TERRAIN.swamp.note
  '陆上单位与舰船不可通过，航空单位可飞越。': 'Unidades terrestres e navios não podem atravessar; unidades aéreas podem sobrevoar.',  // TERRAIN.wall.note
  '每回合提供 100 资金。停留的己方陆上单位每回合恢复 2 HP（需支付资金）。': 'Fornece 100 fundos por turno. Suas unidades terrestres paradas aqui recuperam 2 HP por turno (pagando fundos).',  // TERRAIN.city.note
  '每回合提供 100 资金。可生产陆上单位。停留的己方陆上单位每回合恢复 2 HP（需支付资金）。': 'Fornece 100 fundos por turno. Pode produzir unidades terrestres. Suas unidades terrestres paradas aqui recuperam 2 HP por turno (pagando fundos).',  // TERRAIN.factory.note
  '每回合提供 100 资金。可生产航空单位。停留的己方航空单位与步兵类单位每回合恢复 2 HP（需支付资金）。': 'Fornece 100 fundos por turno. Pode produzir unidades aéreas. Suas unidades aéreas e seus soldados parados aqui recuperam 2 HP por turno (pagando fundos).',  // TERRAIN.airport.note
  '每回合提供 100 资金。可生产舰船。停留的己方舰船与步兵类单位每回合恢复 2 HP（需支付资金）。': 'Fornece 100 fundos por turno. Pode produzir navios. Seus navios e seus soldados parados aqui recuperam 2 HP por turno (pagando fundos).',  // TERRAIN.port.note
  '停留的己方步兵类单位每回合恢复 2 HP（需支付资金）。己方雷达塔 5 格范围内的己方单位攻击 +10%。多座雷达塔的效果不叠加。': 'Seus soldados parados aqui recuperam 2 HP por turno (pagando fundos). Suas unidades a até 5 casas de uma torre de radar sua têm ataque +10%. O efeito de várias torres de radar não se acumula.',  // TERRAIN.tower.note
  '停留的己方步兵类单位每回合恢复 4 HP，相邻四格内的己方步兵类单位每回合恢复 2 HP（需支付资金）。': 'Seus soldados parados aqui recuperam 4 HP por turno, e seus soldados nas quatro casas adjacentes recuperam 2 HP por turno (pagando fundos).',  // TERRAIN.hospital.note
  '停留的己方步兵类单位每回合恢复 2 HP（需支付资金）。位于己方或中立碉堡的单位受到的反击伤害减半，其中远程单位（含投弹手）射程 +1。': 'Seus soldados parados aqui recuperam 2 HP por turno (pagando fundos). Unidades em um bunker seu ou neutro sofrem metade do dano de contra-ataque; entre elas, as unidades de longo alcance (incluindo granadeiros) têm alcance +1.',  // TERRAIN.fort.note
  '可占领建筑的兵种（步兵、破甲兵、摩托兵）进入后可发射一次：指定一格为中心，2 格内所有单位各损失 3 HP（最低保留 1 HP）。': 'Os tipos de unidade que capturam edifícios (infantaria, bazuqueiro e motociclista) podem lançar o míssil uma vez ao entrar: escolha uma casa como centro, e todas as unidades a até 2 casas perdem 3 HP cada (restando no mínimo 1 HP).',  // TERRAIN.silo.note

