  '所求': 'Deseja',  // codex.js:141
  '所惧': 'Teme',  // codex.js:141
  '抛射：移动后仍可攻击。': 'Tiro curvo: pode atacar após se mover.',  // codex.js:169
  '不可攻击相邻的敌方单位，受到相邻敌方单位攻击时也不可反击。': 'Não pode atacar unidades inimigas adjacentes nem contra-atacar quando atacado por elas.',  // codex.js:170
  '攻击时无视目标的地形防御。': 'Ao atacar, ignora a defesa de terreno do alvo.',  // codex.js:171
  '所有阵营均可研究。': 'Todas as facções podem pesquisar.',  // codex.js:196
  '通用与阵营': 'Gerais e de facção',  // codex.js:204
  '克制表　行为攻击方，列为防守方，数值为基础伤害（%）': 'Confrontos: linhas atacam, colunas defendem; valores = dano base (%)',  // codex.js:211
  '攻 ＼ 守': 'Atq \\ Def',  // codex.js:211
  '胜负': 'Vitória e derrota',  // codex.js:235
  '设有天数上限时，到期后先比较各队的收入建筑数，再比较单位总造价。': 'Com limite de dias, ao fim do prazo compara-se primeiro o número de edifícios de renda de cada equipe e depois o custo total das unidades.',  // codex.js:238
  '每座建筑有 20 点占领值，每次占领减去单位当前的 HP。满 HP 的单位需 2 回合完成占领。': 'Cada edifício tem 20 pontos de captura; cada captura subtrai o HP atual da unidade. Uma unidade com HP cheio conclui a captura em 2 turnos.',  // codex.js:247
  '占领中的单位离开或被击毁时，占领值恢复为 20。不可占领友方的建筑。': 'Se a unidade que captura sair ou for destruída, os pontos de captura voltam a 20. Não é possível capturar edifícios aliados.',  // codex.js:248
  '两个单位的 HP 相加，超过 10 的部分按造价返还资金。': 'O HP das duas unidades é somado; o que passar de 10 é devolvido em fundos, conforme o custo.',  // codex.js:250
  '受到不相邻的敌方单位攻击时不可反击。': 'Não há contra-ataque contra unidades inimigas não adjacentes.',  // codex.js:260
  '己方雷达塔 5 格范围内的己方单位攻击 +10%。多座雷达塔的效果不叠加。': 'Suas unidades a até 5 casas de uma torre de radar sua têm ataque +10%. O efeito de várias torres de radar não se acumula.',  // codex.js:276
  '迷雾开启时，己方雷达塔可看见周围 5 格。': 'Com a névoa ativada, suas torres de radar veem 5 casas ao redor.',  // codex.js:276
  '不提供收入。': 'Não fornece renda.',  // codex.js:276
  '可占领建筑的兵种进入后可发射一次：指定一格为中心，2 格内所有单位各损失 3 HP。': 'Os tipos de unidade que capturam edifícios podem lançar o míssil uma vez ao entrar: escolha uma casa como centro, e todas as unidades a até 2 casas perdem 3 HP cada.',  // codex.js:277
  '每击毁一个敌方单位，星级 +1，最高 3 星。': 'Cada unidade inimiga destruída dá +1 estrela, até 3★.',  // codex.js:278
  '每 1 星攻击 +5%、防御 +5%。': 'Cada 1★ dá ataque +5% e defesa +5%.',  // codex.js:278
  '运输单位移动后选择“卸载”，将搭载的单位放置到相邻且可进入的空格。卸载的单位本回合不可再行动。': 'Após mover o transporte, escolha “Desembarcar” e coloque a unidade em uma casa vazia adjacente em que ela possa entrar. A unidade desembarcada não pode mais agir neste turno.',  // codex.js:282
  '技能槽积满后，可在己方回合发动技能，效果持续至己方下回合开始。': 'Com o medidor de poder cheio, você pode ativar o poder no seu turno; o efeito dura até o início do seu próximo turno.',  // codex.js:284
  '技能仅对己方阵营生效。各指挥官的技能见“指挥官”页。': 'O poder só vale para a sua facção. Os poderes de cada comandante estão na página “Comandantes”.',  // codex.js:284
  '特长与阵营特性': 'Especialidade e traço da facção',  // codex.js:285
  '每位指挥官拥有一项特长，开局即生效。': 'Cada comandante tem uma especialidade, que vale desde o início da partida.',  // codex.js:286
  '指挥官同时具有所属阵营的特性，与本局军队的颜色无关。': 'O comandante também tem o traço da facção a que pertence, seja qual for a cor do exército na partida.',  // codex.js:287
  '研究点来源：研究经费、己方科研所，以及各阵营的研究方式（见“阵营”页）。': 'Fontes de pontos de pesquisa: a verba de pesquisa, seus laboratórios e o método de pesquisa de cada facção (veja a página “Facções”).',  // codex.js:294
