  '支付研究经费获得研究点，解锁通用、阵营、指挥官三类科技。': 'Pague a verba de pesquisa para receber pontos de pesquisa e liberar tecnologias de três tipos: gerais, de facção e de comandante.',  // ui-front.js:252
  '阵营数较少的队伍开局资金增加，每回合收入也略有增加。': 'Equipes com menos facções recebem mais fundos iniciais e um pouco mais de renda por turno.',  // ui-front.js:252
