  '{fort}上的远程单位射程 +1，两者不叠加。': 'Alcance +1 para unidades de longo alcance em {fort}; os dois efeitos não se acumulam.',
  '{mountain}上的步兵类远程单位射程 +1，两者不叠加。': 'Alcance +1 para soldados de longo alcance em {mountain}; os dois efeitos não se acumulam.',
  '车辆在{land}修理，航空单位在{airport}修理，舰船在{port}修理。步兵类单位可在任意己方建筑修理。': 'Veículos são reparados em {land}, unidades aéreas em {airport} e navios em {port}. Soldados podem ser reparados em qualquer edifício seu.',
  '车辆在{land}修理，航空单位在{airport}修理。步兵类单位可在任意己方建筑修理。': 'Veículos são reparados em {land} e unidades aéreas em {airport}. Soldados podem ser reparados em qualquer edifício seu.',
  '车辆在{land}修理，舰船在{port}修理。步兵类单位可在任意己方建筑修理。': 'Veículos são reparados em {land} e navios em {port}. Soldados podem ser reparados em qualquer edifício seu.',
  '车辆在{land}修理。步兵类单位可在任意己方建筑修理。': 'Veículos são reparados em {land}. Soldados podem ser reparados em qualquer edifício seu.',
  '与{name}相邻的己方车辆、航空单位、舰船每回合恢复 1 HP（无需支付资金）。': 'Seus veículos, unidades aéreas e navios adjacentes a {name} recuperam 1 HP por turno (sem pagar fundos).',
  '与{name}相邻的己方步兵类单位每回合恢复 2 HP（无需支付资金）。多名{name}的效果不叠加。': 'Seus soldados adjacentes a {name} recuperam 2 HP por turno (sem pagar fundos). O efeito de mais de uma unidade ({name}) não se acumula.',
