  '击毁敌方的强化单位时，获得它强化价的一半（向上取整）。运输单位搭载的强化单位各自计算。': 'Ao destruir uma unidade reforçada inimiga, você recebe metade do custo do reforço dela (arredondada para cima). Cada unidade reforçada a bordo de um transporte é calculada separadamente.',
  '步兵类单位在{mountain}上视野 +3。己方建筑可看见所在的一格，{hq}可看见周围 2 格，{tower}可看见周围 5 格。': 'Soldados têm visão +3 em {mountain}. Seus edifícios veem a própria casa; {hq} vê 2 casas ao redor; {tower} vê 5 casas ao redor.',
