  '完整：每次占领弹出小窗，演出步兵占领建筑的过程；占领司令部时为整屏演出。简短：只在地图上显示跳减的占领值和换色。开启“电脑加速”时，电脑回合自动使用简短演出。': 'Completa: a cada captura abre uma janela que mostra a infantaria tomando o edifício; na captura de um QG, a animação ocupa a tela inteira. Curta: mostra no mapa só os pontos de captura caindo e a troca de cor. Com “CPU acelerada” ativada, os turnos da CPU usam automaticamente a animação curta.',
