  '很久以前，一颗陨星砸进了中央海的正中。': 'Há muito tempo, um meteoro caiu bem no meio do Mar Central.',
  '砸出来的大坑叫海眼。海水从这里进，也从这里出。': 'A grande cova que ele abriu se chama Olho do Mar. É por ela que a água entra, e é por ela que sai.',
  '每过三十年，海水从海眼退下去一次。': 'A cada trinta anos, a água recua pelo Olho do Mar.',
  '海床露出来，上面是成片的陨星碎片。': 'O leito do mar aparece, coberto de fragmentos de meteoro.',
  '谁挖得多，往后三十年谁说了算。': 'Quem extrair mais manda pelos próximos trinta anos.',
  '所以每退一次潮，四国就打一次仗。': 'Por isso, a cada vazante, as quatro nações entram em guerra.',
  '今年又退潮了。': 'Este ano a maré recuou de novo.',
  '这一次，海眼里开出来一支黑色的军队。': 'Desta vez, um exército negro saiu de dentro do Olho do Mar.',
  '赤焰的新人燕烽，头一回带兵。': 'Yan Feng, novata da Chama Carmesim, comanda tropas pela primeira vez.',
  '到了再说！': 'Chegando lá, a gente vê!',
