  '射程 3–6，只能攻击航空单位，伤害极高。移动后不可攻击。': 'Alcance 3–6; só pode atacar unidades aéreas, com dano altíssimo. Não pode atacar após se mover.',
  '只能攻击航空单位，用于争夺制空权。': 'Só pode atacar unidades aéreas; serve para disputar o domínio aéreo.',
  '只能攻击舰船，擅长攻击战列舰。航空单位和战列舰不可攻击潜艇。不敌驱逐舰。': 'Só pode atacar navios; é eficaz contra encouraçados. Unidades aéreas e encouraçados não podem atacar submarinos. É fraco contra destróieres.',
  '只能在道路、桥梁和建筑上移动。射程 1–3，移动后只能攻击相邻目标。可搭载 2 个徒步的步兵类单位（摩托兵除外）。攻击与防御介于中型坦克和重型坦克之间。': 'Só anda por estradas, pontes e edifícios. Alcance 1–3; após se mover, só pode atacar alvos adjacentes. Pode transportar 2 soldados a pé (exceto motociclistas). Ataque e defesa ficam entre os do tanque médio e os do tanque pesado.',
  '隐形的航空单位：敌方只有相邻时才能发现（迷雾关闭时也有效）。对航空单位伤害高，对陆上单位伤害中等。': 'Unidade aérea furtiva: o inimigo só a detecta quando está adjacente (também com a névoa desativada). Dano alto contra unidades aéreas e médio contra unidades terrestres.',
  '射程 2–5 的舰船，移动后不可攻击。上一个己方回合没有攻击时处于下潜状态：敌方只有相邻时才能发现（迷雾关闭时也有效）。': 'Navio com alcance 2–5. Não pode atacar depois de se mover. Se não disparou no seu turno anterior, fica submerso: o inimigo só o detecta quando está adjacente (também com a névoa desativada).',
  '陆上单位结束移动停在这一格时拾取，获得 1–3 份陨星碎片（每个碎片堆在开局时随机决定），这一格变为碎片坑（与荒地相同）。轮式车辆的移动消耗为 3。': 'Unidades terrestres que terminam o movimento nesta casa a coletam e recebem 1–3 fragmentos de meteoro (quantidade sorteada para cada pilha no início da partida); a casa vira cova de fragmentos (igual a um ermo). Veículos de rodas têm custo de movimento 3.',
  '迷雾开启时，森林中的单位只有相邻时才会被发现。': 'Com a névoa ativada, unidades em florestas só são reveladas quando adjacentes.',
  '只有步兵类单位可以进入。狙击手、投弹手在山地上射程 +1。迷雾开启时，步兵类单位在山地上视野 +3。': 'Só soldados podem entrar. Franco-atiradores e granadeiros têm alcance +1 em montanhas. Com a névoa ativada, soldados têm visão +3 em montanhas.',
  '登陆艇可以进入。陆上单位可以在这里搭乘登陆艇；登陆艇可以在这里把搭载的单位卸载到相邻的格子。': 'Barcaças podem entrar. Unidades terrestres podem embarcar em uma barcaça aqui; uma barcaça aqui pode desembarcar suas unidades nas casas adjacentes.',
  '只有舰船可以进入，移动消耗 2，地形防御 2 星。': 'Só navios podem entrar; custo de movimento 2, defesa de terreno 2★.',
