  '只有一名玩家对战电脑的对局才评分。': 'Só partidas de um jogador contra a CPU são avaliadas.',
  '开局资金、建筑收入、人数补偿使用这张地图的默认设置时才评分。': 'A partida só é avaliada quando os fundos iniciais, a renda por edifício e a compensação usam as configurações padrão deste mapa.',
  '队伍使用这张地图的默认分法时才评分。': 'A partida só é avaliada quando as equipes usam a divisão padrão deste mapa.',
  '这位指挥官首次获得 S 评价': 'Primeiro rank S com este comandante',
